use std::cmp;

// Complex number struct with 32-bit integer components
#[derive(Debug, Clone, PartialEq)]
struct Complex {
    re: i32,
    im: i32,
}

impl Complex {
    fn new(re: i32, im: i32) -> Self {
        Complex { re, im }
    }
}

fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    // Fixed machine epsilon as defined in the problem
    const MACHINE_EPSILON: i32 = 2;
    
    // Calculate the threshold for "close to zero"
    let threshold = tol.saturating_mul(MACHINE_EPSILON);
    
    // Check if all elements have imaginary parts close to zero
    let all_close = arr.iter().all(|c| {
        // Use absolute value of imaginary part
        let abs_im = c.im.abs();
        abs_im <= threshold
    });
    
    if all_close {
        // Create new array with imaginary parts set to zero
        arr.into_iter()
            .map(|c| Complex::new(c.re, 0))
            .collect()
    } else {
        // Return the input array unchanged
        arr
    }
}

